import{_ as t,o as a,c as s,a2 as o}from"./chunks/framework.CyZTVJbV.js";const g=JSON.parse('{"title":"AI-LLM multimodal testing — image, audio, MCP handshake, agent state","description":"","frontmatter":{},"headers":[],"relativePath":"concepts/ai-llm-multimodal-testing.md","filePath":"concepts/ai-llm-multimodal-testing.md"}'),i={name:"concepts/ai-llm-multimodal-testing.md"};function n(r,e,l,c,h,d){return a(),s("div",null,[...e[0]||(e[0]=[o(`<h1 id="ai-llm-multimodal-testing-—-image-audio-mcp-handshake-agent-state" tabindex="-1">AI-LLM multimodal testing — image, audio, MCP handshake, agent state <a class="header-anchor" href="#ai-llm-multimodal-testing-—-image-audio-mcp-handshake-agent-state" aria-label="Permalink to &quot;AI-LLM multimodal testing — image, audio, MCP handshake, agent state&quot;">​</a></h1><p>v1.12 established the non-determinism SSOT for AI-LLM providers (<a href="./ai-llm-testing"><code>ai-llm-testing.md</code></a>): the mock is deterministic on purpose, and the release gate measures how far real drifts from the mock per axis. v1.15 extends that stance to three shapes v1.12 did not cover — <strong>multimodal inputs</strong> (image + audio), <strong>MCP protocol handshakes</strong>, and <strong>agent state machines</strong>.</p><p>Each of these opens new failure modes that a purely text-only 11-axis release gate cannot catch. This document is the SSOT for the design decisions kiwa took to keep those failure modes testable.</p><h2 id="the-three-shapes-v1-15-adds" tabindex="-1">The three shapes v1.15 adds <a class="header-anchor" href="#the-three-shapes-v1-15-adds" aria-label="Permalink to &quot;The three shapes v1.15 adds&quot;">​</a></h2><table tabindex="0"><thead><tr><th>shape</th><th>v1.12 coverage</th><th>v1.15 coverage</th></tr></thead><tbody><tr><td>text-only chat + streaming + tool_use</td><td>4 SDK mocks + 11-axis gate</td><td>unchanged</td></tr><tr><td>multimodal input (image + audio)</td><td>not supported</td><td><code>@kiwa-test/ai-llm</code> v0.2 across all 4 SDKs</td></tr><tr><td>tool provisioning via process boundary</td><td>app-internal function tools only</td><td><code>@kiwa-test/mcp</code> v0.1 (JSON-RPC 2.0)</td></tr><tr><td>stateful multi-turn agent orchestration</td><td>text-only Anthropic/OpenAI/Vercel/LangChain loops</td><td><code>@kiwa-test/agent</code> v0.1 (LangGraph + Assistants v2)</td></tr></tbody></table><p>All three land as <strong>additive</strong> — v1.12 test suites keep passing on their v0.1 configuration.</p><h2 id="concept-1-—-image-tokens-are-prompt-tokens-but-the-byte-content-is-not-the-key" tabindex="-1">Concept 1 — image tokens are prompt tokens, but the byte content is not the key <a class="header-anchor" href="#concept-1-—-image-tokens-are-prompt-tokens-but-the-byte-content-is-not-the-key" aria-label="Permalink to &quot;Concept 1 — image tokens are prompt tokens, but the byte content is not the key&quot;">​</a></h2><p>Real Anthropic and OpenAI vision APIs charge image tokens against the prompt-token budget. A 1024×1024 image at <code>detail: &#39;high&#39;</code> costs roughly 1500 prompt tokens on Anthropic and 1105–1445 on OpenAI, depending on tile count. The kiwa mock rounds this to a single knob — <code>imageTokenCost</code> — and multiplies by the detail hint (0.5 / 0.8 / 1.0) so the numbers stay close enough for release-gate assertions to be meaningful.</p><p>The reason the mock&#39;s response-bank lookup <strong>does not key on image bytes</strong> is not simplification for its own sake. It is a deliberate consequence of how real LLM behaviour differs across image content:</p><ul><li>The <strong>same image</strong> submitted twice against a <code>temperature &gt; 0</code> model returns <strong>different text</strong> each time.</li><li>The <strong>image bytes</strong> never appear in the reply; only their interpretation does.</li><li>Tests assert on the <strong>text output</strong> and the <strong>prompt-token accounting</strong>, not on the pixels.</li></ul><p>Keying the response bank on the last text-carrying user block preserves the v1.12 shape (deterministic replies against a canned bank) while letting the mock still count image tokens correctly. If a test needs to prove &quot;OCR was requested against a receipt&quot;, the assertion is on the reply text (&quot;Total: $12.30&quot;) and the <code>usage.input_tokens</code> count, never on the image bytes themselves.</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// v1.15 style — deterministic reply against canned bank + prompt-token assertion</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">expect</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(res.content[</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">].text).</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">toContain</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;Total: $12.30&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">expect</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(res.usage.input_tokens).</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">toBeGreaterThan</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1500</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">); </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// proves the image was counted</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">expect</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(res._kiwa.costUsd).</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">toBeGreaterThan</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);         </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// proves cost tracking picked it up</span></span></code></pre></div><h2 id="concept-2-—-audio-has-a-duration-axis-but-no-wall-clock-in-the-mock" tabindex="-1">Concept 2 — audio has a duration axis but no wall-clock in the mock <a class="header-anchor" href="#concept-2-—-audio-has-a-duration-axis-but-no-wall-clock-in-the-mock" aria-label="Permalink to &quot;Concept 2 — audio has a duration axis but no wall-clock in the mock&quot;">​</a></h2><p>Whisper transcription costs $0.006 per minute in real OpenAI. The kiwa mock represents this as <code>audioTokenCost</code> (default 500 base tokens) that scales linearly per 30 s of duration. Tests specify the duration in the source metadata; the mock never fetches or plays audio.</p><p>Two design consequences follow.</p><ul><li><strong>URLs are not resolved.</strong> The mock keys transcription lookups via <code>toTranscriptionKey({ url })</code>. A <code>404</code> on the URL cannot break a test because no HTTP request happens.</li><li><strong><code>defaultTranscription</code> is a safety net, not a bug.</strong> Production code always deals with unfamiliar audio; the mock refuses to throw when a source is unknown. Assertions that a specific source was hit are text-equality assertions against the known transcription.</li></ul><p>The pattern to prove &quot;audio was processed and yielded segments&quot; is text + segment count:</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">expect</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(trans.text).</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">toBe</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;hello kiwa&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">expect</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(trans.segments).</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">toHaveLength</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><p>The pattern to prove &quot;audio was billed correctly&quot; is duration-scaled cost against the mock&#39;s known cost table.</p><h2 id="concept-3-—-mcp-handshake-order-is-a-first-class-invariant" tabindex="-1">Concept 3 — MCP handshake order is a first-class invariant <a class="header-anchor" href="#concept-3-—-mcp-handshake-order-is-a-first-class-invariant" aria-label="Permalink to &quot;Concept 3 — MCP handshake order is a first-class invariant&quot;">​</a></h2><p>The Model Context Protocol wraps tool exchange in JSON-RPC 2.0 with a hard-coded op order:</p><ol><li><code>initialize</code> (client → server, sync)</li><li><code>notifications/initialized</code> (client → server, notification)</li><li><code>tools/list</code> (client → server, sync)</li><li><code>tools/call</code> (client → server, sync)</li></ol><p>Real MCP clients enforce this order because a <code>tools/list</code> before <code>initialize</code> gives the server no chance to negotiate protocol version + capabilities. The kiwa mock enforces the same order <strong>explicitly</strong> — a <code>tools/list</code> call before <code>initialize</code> returns <code>-32002 NotInitialized</code>. A mock that skipped this check would let bugs slip through.</p><p>The <code>-32002</code> code, along with the other three MCP-specific extensions (<code>-32000</code> ToolExecutionError, <code>-32001</code> ToolSchemaError, <code>-32003</code> ToolNotFound), is part of the mock&#39;s contract. Tests that assert on these codes will keep passing when the <code>InMemoryTransport</code> is swapped for a stdio child process transport, because the wire format is identical.</p><p>The response-bank pattern from v1.12 does not apply directly to MCP because MCP tool calls are function invocations, not chat replies. Instead, <code>@kiwa-test/mcp</code> uses a <strong>tool registry</strong>: each tool has a name, description, JSONSchema input schema, and handler. The handler is a plain function that runs synchronously in the mock and returns a <code>ToolResult</code> (<code>content: [{ type: &#39;text&#39;, text: &#39;...&#39; }]</code> in the common case).</p><h2 id="concept-4-—-agent-state-machines-are-graphs-not-chat-logs" tabindex="-1">Concept 4 — agent state machines are graphs, not chat logs <a class="header-anchor" href="#concept-4-—-agent-state-machines-are-graphs-not-chat-logs" aria-label="Permalink to &quot;Concept 4 — agent state machines are graphs, not chat logs&quot;">​</a></h2><p><code>@kiwa-test/agent</code> covers two orchestration styles under one API:</p><ul><li><strong>LangGraph-style <code>StateGraph</code></strong> — declarative dataflow. Nodes are pure state → patch functions; edges are unconditional (v0.1). The graph is validated on <code>.compile()</code> with 6 fail-fast checks (see <a href="./../tutorials/18-agent-orchestration">Tutorial 18</a> for the list).</li><li><strong>OpenAI Assistants v2</strong> — stateful multi-turn. Runs move through 5 statuses (<code>queued</code> / <code>in_progress</code> / <code>requires_action</code> / <code>completed</code> / <code>failed</code>); tool outputs are submitted asynchronously via <code>submitToolOutputs</code>.</li></ul><p>Both styles share a common failure mode: <strong>runaway loops</strong>. A conditional edge that never terminates, or an assistant handler that emits <code>tool_calls</code> on every turn without ever emitting <code>message</code>, blows the token budget in production. The mock guards this with a <code>maxSteps</code> cap (default 100 for LangGraph, 50 for Assistants v2 polling); tests that exceed the cap fail with a clear error, not a hang.</p><p>The mock&#39;s Assistants v2 client resolves handlers synchronously so the <code>in_progress</code> step is folded into the initial <code>poll</code> call. Real Assistants v2 exposes <code>in_progress</code> when polling during handler execution; tests do not need to sleep-poll the mock to observe it. This is the same trade-off as the multimodal mock: the mock is deterministic on purpose, and the release gate measures how far real diverges.</p><h2 id="concept-5-—-mcp-agent-multimodal-roll-into-the-11-axis-gate-but-only-when-combined-with-kiwa-test-ai" tabindex="-1">Concept 5 — MCP + agent + multimodal roll into the 11-axis gate, but only when combined with <code>@kiwa-test/ai-*</code> <a class="header-anchor" href="#concept-5-—-mcp-agent-multimodal-roll-into-the-11-axis-gate-but-only-when-combined-with-kiwa-test-ai" aria-label="Permalink to &quot;Concept 5 — MCP + agent + multimodal roll into the 11-axis gate, but only when combined with \`@kiwa-test/ai-*\`&quot;">​</a></h2><p>The <code>evaluateReleaseGate</code> 11-axis branch triggers on the provider prefix <code>@kiwa-test/ai-*</code>. <code>@kiwa-test/mcp</code> and <code>@kiwa-test/agent</code> on their own are not AI-LLM providers — they are protocol + orchestration wrappers. A dogfood app that uses <code>@kiwa-test/mcp</code> to expose tools <strong>plus</strong> <code>@kiwa-test/ai-llm</code> to drive a Claude client rolls into the 11-axis gate because the provider string is <code>@kiwa-test/ai-llm/&lt;subpath&gt;</code>; the MCP overhead shows up in latency + token counts, not as separate axes.</p><p>Concretely, the dogfood app <code>examples/dogfood-mcp-tool-agent</code> reports its provider as <code>@kiwa-test/ai-llm/mcp-tool-agent</code>. This means:</p><ul><li><code>cost.perRequestUsd</code> counts the full Anthropic + MCP roundtrip on the real side, and the mock cost of both on the mock side.</li><li><code>latency.p95Ms</code> counts the full JSON-RPC + Claude latency.</li><li><code>token.totalTokens</code> counts the full prompt + completion tokens including any tool-schema material Claude sees.</li><li><code>accuracy.score</code> compares the final Claude reply (post-tool-loop) against the real system.</li></ul><p>No new axes are needed. The MCP handshake + tool-call shape is a <strong>fidelity ratio contribution</strong> — a mock that skipped the handshake would fail the 7-axis fidelity check, which is the existing v1.11 axis.</p><h2 id="concept-6-—-agent-state-gotchas-that-only-appear-in-multi-turn-tests" tabindex="-1">Concept 6 — agent-state gotchas that only appear in multi-turn tests <a class="header-anchor" href="#concept-6-—-agent-state-gotchas-that-only-appear-in-multi-turn-tests" aria-label="Permalink to &quot;Concept 6 — agent-state gotchas that only appear in multi-turn tests&quot;">​</a></h2><p>Two failure modes are specific to agent orchestration and only show up in tests that walk 3+ turns.</p><ul><li><strong>The response bank turn-0 lookup collision.</strong> Anthropic Claude&#39;s tool-use loop delivers follow-up turns as user messages whose content is a list of <code>tool_result</code> blocks. The mock&#39;s response-bank lookup keys on the last text-carrying user block, which for turn 2+ is still the original prompt. If tests reuse a single mock instance across turns without preparing distinct bank entries for each turn, the mock returns the turn-0 reply on every turn — an infinite tool-use loop. The pattern that avoids this is to construct a <strong>fresh mock instance per iteration</strong> with a distinct response bank keyed by the ordered tool state (turn 0 = tool A, turn 1 = tool B, turn 2 = finalisation). <code>examples/dogfood-mcp-tool-agent/src/adapters/mock.ts</code> implements this pattern; copy it for any multi-turn tool-loop test.</li><li><strong>The Assistants v2 <code>poll</code> after <code>cancel</code>.</strong> Cancelling a queued run flips it to <code>failed</code> with <code>lastError.code = &#39;cancelled&#39;</code>. Polling that run afterwards returns the same terminal step, not an error. Tests that expect <code>poll</code> to throw on a cancelled run will fail against the mock — this matches real Assistants v2 behaviour.</li></ul><h2 id="where-the-code-lives" tabindex="-1">Where the code lives <a class="header-anchor" href="#where-the-code-lives" aria-label="Permalink to &quot;Where the code lives&quot;">​</a></h2><ul><li><strong>Multimodal mocks</strong> — <a href="https://github.com/cardene777/kiwa/blob/main/packages/ai-llm/src/multimodal.ts" target="_blank" rel="noreferrer"><code>packages/ai-llm/src/multimodal.ts</code></a></li><li><strong>Whisper mock</strong> — <a href="https://github.com/cardene777/kiwa/blob/main/packages/ai-llm/src/openai.ts" target="_blank" rel="noreferrer"><code>packages/ai-llm/src/openai.ts</code></a> (<code>audio.transcriptions.create</code>)</li><li><strong>MCP server</strong> — <a href="https://github.com/cardene777/kiwa/blob/main/packages/mcp/src/server.ts" target="_blank" rel="noreferrer"><code>packages/mcp/src/server.ts</code></a></li><li><strong>MCP client + transport</strong> — <a href="https://github.com/cardene777/kiwa/blob/main/packages/mcp/src/client.ts" target="_blank" rel="noreferrer"><code>packages/mcp/src/client.ts</code></a></li><li><strong>MCP fixture tools</strong> — <a href="https://github.com/cardene777/kiwa/blob/main/packages/mcp/src/fixture.ts" target="_blank" rel="noreferrer"><code>packages/mcp/src/fixture.ts</code></a> (<code>registerAllFixtureTools</code>)</li><li><strong>LangGraph state machine</strong> — <a href="https://github.com/cardene777/kiwa/blob/main/packages/agent/src/langgraph.ts" target="_blank" rel="noreferrer"><code>packages/agent/src/langgraph.ts</code></a> + <a href="https://github.com/cardene777/kiwa/blob/main/packages/agent/src/state-machine.ts" target="_blank" rel="noreferrer"><code>packages/agent/src/state-machine.ts</code></a></li><li><strong>Assistants v2 client</strong> — <a href="https://github.com/cardene777/kiwa/blob/main/packages/agent/src/openai-assistants.ts" target="_blank" rel="noreferrer"><code>packages/agent/src/openai-assistants.ts</code></a></li><li><strong>Dogfood app — multimodal</strong> — <a href="https://github.com/cardene777/kiwa/tree/main/examples/dogfood-multimodal-chat" target="_blank" rel="noreferrer"><code>examples/dogfood-multimodal-chat/</code></a></li><li><strong>Dogfood app — MCP + agent</strong> — <a href="https://github.com/cardene777/kiwa/tree/main/examples/dogfood-mcp-tool-agent" target="_blank" rel="noreferrer"><code>examples/dogfood-mcp-tool-agent/</code></a></li></ul><h2 id="when-to-reach-for-each-shape" tabindex="-1">When to reach for each shape <a class="header-anchor" href="#when-to-reach-for-each-shape" aria-label="Permalink to &quot;When to reach for each shape&quot;">​</a></h2><ul><li><strong>Text-only chat</strong> — v1.12 patterns still apply. Do not adopt multimodal / MCP / agent unless the app actually needs them.</li><li><strong>Vision or OCR</strong> — v1.15 multimodal on the appropriate SDK. Anthropic vision for classification / description, OpenAI vision with <code>detail: &#39;high&#39;</code> for OCR / small-text answers.</li><li><strong>Audio input</strong> — v1.15 Whisper on <code>@kiwa-test/ai-llm</code> OpenAI mock. Keep audio-duration assertions in the test to prove the cost path.</li><li><strong>Tools behind a process boundary</strong> — v1.15 MCP. Direct app-internal tools should still use native Claude / OpenAI tool-use to avoid a JSON-RPC hop that provides no benefit.</li><li><strong>Multi-turn stateful conversation</strong> — v1.15 agent. Pick LangGraph for declarative dataflow, Assistants v2 for OpenAI-shaped stateful multi-turn.</li></ul><h2 id="what-is-deliberately-not-in-scope-for-v1-15" tabindex="-1">What is deliberately not in scope for v1.15 <a class="header-anchor" href="#what-is-deliberately-not-in-scope-for-v1-15" aria-label="Permalink to &quot;What is deliberately not in scope for v1.15&quot;">​</a></h2><ul><li><strong>Image generation</strong> (Anthropic image output / DALL·E / Imagen) — the multimodal mock covers input only. Output-side image generation is a separate mock surface and lands in a future release.</li><li><strong>Text-to-speech</strong> — mirror of image generation. Whisper covers speech-to-text; TTS is out of scope for v1.15.</li><li><strong>MCP resources / prompts / sampling / logging ops</strong> — v0.1 covers the tool-use half. The remaining ops are additive and land in <code>@kiwa-test/mcp</code> v0.2.</li><li><strong>LangGraph conditional edges / channels reducers / interrupts / checkpointers</strong> — v0.1 covers unconditional dataflow. Advanced graph shapes are additive and land in <code>@kiwa-test/agent</code> v0.2.</li><li><strong>Live streaming for Assistants v2 runs (SSE)</strong> — v0.1 exposes synchronous <code>poll</code>. SSE streaming is on the v0.2 roadmap.</li></ul><h2 id="reading-list" tabindex="-1">Reading list <a class="header-anchor" href="#reading-list" aria-label="Permalink to &quot;Reading list&quot;">​</a></h2><ul><li><a href="./ai-llm-testing">AI-LLM testing (v1.12 SSOT)</a> — non-determinism + 11-axis gate, unchanged</li><li><a href="./realtime-testing">Realtime testing (v1.13 SSOT)</a> — time-axis mock; the mock-time-line pattern applies to Assistants v2 polling too</li><li><a href="./../tutorials/16-multimodal-chat">Tutorial 16 — Multimodal chat</a></li><li><a href="./../tutorials/17-mcp-tool-agent">Tutorial 17 — MCP tool-use agent</a></li><li><a href="./../tutorials/18-agent-orchestration">Tutorial 18 — Agent orchestration</a></li><li><a href="https://github.com/cardene777/kiwa/blob/main/packages/ai-llm/README.md" target="_blank" rel="noreferrer"><code>@kiwa-test/ai-llm</code> README</a></li><li><a href="https://github.com/cardene777/kiwa/blob/main/packages/mcp/README.md" target="_blank" rel="noreferrer"><code>@kiwa-test/mcp</code> README</a></li><li><a href="https://github.com/cardene777/kiwa/blob/main/packages/agent/README.md" target="_blank" rel="noreferrer"><code>@kiwa-test/agent</code> README</a></li></ul><h2 id="takeaways" tabindex="-1">Takeaways <a class="header-anchor" href="#takeaways" aria-label="Permalink to &quot;Takeaways&quot;">​</a></h2><ul><li>Multimodal inputs cost prompt tokens, not response tokens. The mock counts them; the response bank keys on text so replies stay deterministic.</li><li>Whisper URLs are never resolved by the mock. Duration is metadata; assertions are on transcribed text + segment count.</li><li>MCP handshake order is a first-class invariant. The mock enforces it — a <code>tools/list</code> before <code>initialize</code> returns <code>-32002</code>.</li><li>Agent orchestration adds two new failure modes: <strong>response-bank turn-0 collision</strong> on Anthropic tool-use loops (mitigated by fresh mock per iteration) and <strong>poll-after-cancel</strong> returning the terminal step instead of throwing.</li><li>v1.15 mocks roll into the existing 11-axis gate through the <code>@kiwa-test/ai-*</code> provider prefix. No new axes; MCP + agent overhead is fidelity + latency + token spend that the existing axes already measure.</li></ul>`,48)])])}const u=t(i,[["render",n]]);export{g as __pageData,u as default};
